template:
struct Config {
    endpoint: Option<String>,
}

fn endpoint_str(cfg: &Config) -> Option<&str> {
    cfg.endpoint.⟦slot1⟧
}

fn main() {
    let cfg = Config {
        endpoint: Some(String::from("api")),
    };
    let ep = endpoint_str(⟦slot2⟧);
    println!("{:?}: {}", ep, cfg.endpoint.is_some());
}

tests:
#[test]
fn test_endpoint() {
    let cfg = Config { endpoint: Some(String::from("api")) };
    assert_eq!(endpoint_str(&cfg), Some("api"));
    assert!(cfg.endpoint.is_some());
}
